import os
from typing import Any

from qwen_vl_utils import process_vision_info
from smolagents.models import ChatMessage, MessageRole, Model
from transformers import AutoProcessor, Qwen2_5_VLForConditionalGeneration


class QwenVLModel(Model):
    """Model wrapper for Qwen2.5VL"""

    def __init__(self, model_path: str = "Qwen/Qwen2.5-VL-3B-Instruct", device: str = "auto"):
        super().__init__()
        self.model_path = model_path
        self.device = device
        self.model_id = model_path
        self.model = Qwen2_5_VLForConditionalGeneration.from_pretrained(
            model_path, torch_dtype="auto", device_map=device
        )
        self.processor = AutoProcessor.from_pretrained(model_path)

    def __call__(
        self, messages: list[dict[str, Any]], stop_sequences: list[str] | None = None, **kwargs
    ) -> ChatMessage:
        """Convert a list of messages to a model input and run inference"""

        # Count images in messages - debug
        image_count = 0
        for msg in messages:
            if isinstance(msg.get("content"), list):
                for item in msg["content"]:
                    if isinstance(item, dict) and item.get("type") == "image":
                        image_count += 1

        print(f"QwenVLModel received {len(messages)} messages with {image_count} images")

        # Format the messages for Qwen2.5VL
        formatted_messages = []

        for msg in messages:
            role = msg["role"]
            if isinstance(msg["content"], list):
                content = []
                for item in msg["content"]:
                    if item["type"] == "text":
                        content.append({"type": "text", "text": item["text"]})
                    elif item["type"] == "image":
                        # Handle image path or direct image object
                        if isinstance(item["image"], str):
                            print("Image in memory")
                            content.append({"type": "image", "image": item["image"]})
                        else:
                            print("Image in temp file")
                            # Save temporary image file
                            temp_img_path = "temp_image.png"
                            item["image"].save(temp_img_path)
                            content.append({"type": "image", "image": temp_img_path})
            else:
                content = [{"type": "text", "text": msg["content"]}]

            formatted_messages.append({"role": role, "content": content})

        # Prepare for inference
        text = self.processor.apply_chat_template(formatted_messages, tokenize=False, add_generation_prompt=True)
        image_inputs, video_inputs = process_vision_info(formatted_messages)
        inputs = self.processor(
            text=[text],
            images=image_inputs,
            videos=video_inputs,
            padding=True,
            return_tensors="pt",
        )
        inputs = inputs.to(self.model.device)

        # Generate the response
        generated_ids = self.model.generate(**inputs, max_new_tokens=512)
        generated_ids_trimmed = [out_ids[len(in_ids) :] for in_ids, out_ids in zip(inputs.input_ids, generated_ids)]
        output_text = self.processor.batch_decode(
            generated_ids_trimmed, skip_special_tokens=True, clean_up_tokenization_spaces=False
        )[0]

        # Clean up any temporary files
        if os.path.exists("temp_image.png"):
            os.remove("temp_image.png")

        return ChatMessage(role=MessageRole.ASSISTANT, content=output_text)

    def to_dict(self) -> dict[str, Any]:
        """Convert the model to a dictionary"""
        return {"class": self.__class__.__name__, "model_path": self.model_path, "device": self.device}

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> "QwenVLModel":
        """Create a model from a dictionary"""
        return cls(model_path=data.get("model_path", "Qwen/Qwen2.5-VL-3B-Instruct"), device=data.get("device", "auto"))

from pydantic import BaseModel, Field


class NormalizedClickCoordinates(BaseModel):
    """Represents a click position with x, y coordinates, normalized to the image width and height."""

    x: float = Field(ge=0.0, le=1.0)
    y: float = Field(ge=0.0, le=1.0)

    @classmethod
    def from_xy(
        cls, xy: tuple[float, float], image_width: int = 1, image_height: int = 1
    ) -> "NormalizedClickCoordinates":
        """Create a NormalizedClickCoordinates from a tuple of coordinates."""
        return cls(x=xy[0] / image_width, y=xy[1] / image_height)

    def to_xy_string(self) -> str:
        """Convert the click position to a click center position string."""
        return f"{self.x:.3f}, {self.y:.3f}"

    def to_xy(self) -> tuple[float, float]:
        """Convert the click position to a click center position."""
        return (self.x, self.y)


class NormalizedBoundingBox(BaseModel):
    """Represents a normalized bounding box with x, y, width, height coordinates."""

    x: float = Field(ge=0.0, le=1.0)
    y: float = Field(ge=0.0, le=1.0)
    width: float = Field(ge=0.0, le=1.0)
    height: float = Field(ge=0.0, le=1.0)

    @classmethod
    def from_xywh(
        cls, xywh_bbox: tuple[float, float, float, float], image_width: int = 1, image_height: int = 1
    ) -> "NormalizedBoundingBox":
        return cls(
            x=xywh_bbox[0] / image_width,
            y=xywh_bbox[1] / image_height,
            width=xywh_bbox[2] / image_width,
            height=xywh_bbox[3] / image_height,
        )

    @classmethod
    def from_xyxy(
        cls, xyxy_bbox: tuple[float, float, float, float], image_width: int = 1, image_height: int = 1
    ) -> "NormalizedBoundingBox":
        return cls(
            x=xyxy_bbox[0] / image_width,
            y=xyxy_bbox[1] / image_height,
            width=(xyxy_bbox[2] - xyxy_bbox[0]) / image_width,
            height=(xyxy_bbox[3] - xyxy_bbox[1]) / image_height,
        )

    @classmethod
    def from_xywh_string(cls, bbox_str: str, image_width: int, image_height: int) -> "NormalizedBoundingBox":
        """Create a NormalizedBoundingBox from a comma-separated string of coordinates."""
        x, y, w, h = map(float, bbox_str.split(","))
        return cls(x=x / image_width, y=y / image_height, width=w / image_width, height=h / image_height)

    def to_click_center_position_string(self) -> str:
        """Convert the bounding box to a click center position string."""
        return f"{self.x + self.width / 2:.3f}, {self.y + self.height / 2:.3f}"

    def to_click_center_position(self) -> tuple[float, float]:
        """Convert the bounding box to a click center position."""
        return (self.x + self.width / 2, self.y + self.height / 2)

    def to_xyxy(self) -> tuple[float, float, float, float]:
        """Convert the bounding box to a tuple of (x1, y1, x2, y2)."""
        return (
            self.x,
            self.y,
            self.x + self.width,
            self.y + self.height,
        )

    def to_xywh(self) -> tuple[float, float, float, float]:
        """Convert the bounding box to a tuple of (x, y, width, height)."""
        return (
            self.x,
            self.y,
            self.width,
            self.height,
        )

from abc import ABC, abstractmethod
from typing import Literal

from pydantic import BaseModel


class IPAddr(BaseModel):
    ip_address: str
    host_port: dict[int, int]


class Provider(ABC, BaseModel):
    @abstractmethod
    def start_emulator(self):
        """
        Method to start the emulator.
        """
        ...

    @abstractmethod
    def get_ip_address(self) -> IPAddr:
        """
        Method to get the private IP address of the VM. Private IP means inside the VPC.
        """
        ...

    @abstractmethod
    def save_state(self, snapshot_name: str):
        """
        Method to save the state of the VM.
        """
        ...

    @abstractmethod
    def revert_to_snapshot(self, snapshot_name: str) -> str:
        """
        Method to revert the VM to a given snapshot.
        """
        ...

    @abstractmethod
    def reset(self):
        """
        Method to reset the VM.
        """
        ...

    @abstractmethod
    def stop_emulator(self):
        """
        Method to stop the emulator.
        """
        ...

    class Config:
        arbitrary_types_allowed = True


class FakeProviderConfig(BaseModel):
    PROVIDER_NAME: Literal["fake"] = "fake"


class FakeProvider(Provider):
    def start_emulator(self):
        pass

    def get_ip_address(self) -> IPAddr:
        return IPAddr(ip_address="127.0.0.1", host_port={})

    def save_state(self, snapshot_name: str):
        pass

    def revert_to_snapshot(self, snapshot_name: str):
        pass

    def stop_emulator(self):
        pass

import logging
from typing import Annotated, TypeAlias, overload

from pydantic import Field

from screensuite.agents.remote_env.docker.provider import (
    DockerProvider,
    DockerProviderConfig,
)
from screensuite.agents.remote_env.provider import FakeProvider, FakeProviderConfig

logger = logging.getLogger()

ProviderConfig: TypeAlias = Annotated[
    DockerProviderConfig | FakeProviderConfig,
    Field(discriminator="PROVIDER_NAME"),
]
ProviderClient: TypeAlias = DockerProvider | FakeProvider


# fmt: off
@overload
def create_remote_env_provider(config: DockerProviderConfig) -> DockerProvider: ...
@overload
def create_remote_env_provider(config: ProviderConfig) -> ProviderClient: ...
# fmt: on
def create_remote_env_provider(config: ProviderConfig) -> ProviderClient:
    if config.PROVIDER_NAME == "docker":
        return DockerProvider(config=config)
    raise NotImplementedError(f"Provider {config.PROVIDER_NAME} not implemented")

import json
from typing import Any, Literal

from pydantic import BaseModel


class Operation(BaseModel):
    """Represents an atomic action to be performed."""

    type: Literal["click", "open_app", "scroll", "type", "wait", "navigate_back", "navigate_home"]
    args: dict[str, Any]

    @classmethod
    def from_json_android_control(cls, json_str: str) -> "Operation":
        """Create an Operation from a JSON string."""
        dict_str = json.loads(json_str)
        return cls(type=dict_str.pop("action_type"), args=dict_str)

    def to_string(self) -> str:
        """Convert the operation to a human-readable string, for instance `click(254,753)`."""
        return self.type.lower() + "(" + ",".join([repr(v).replace("'", '"') for v in self.args.values()]) + ")"


class Action(BaseModel):
    """Represents an action to be performed, which is a code representation of successive operations."""

    operations: list[Operation]

    def to_string(self) -> str:
        """Convert the action to a human-readable string, for instance `click(254,753); type("hello")`."""
        return "; ".join([operation.to_string() for operation in self.operations])
